import {BATTLE_TRANSITION_DURATION} from '../../../../src/js/toy-room/BattleConfig.js';
import {renderArenaTemple} from '../../../../src/js/toy-room/ArenaEnvironment.js';
import {ToyRoomPhase} from '../../../../src/js/toy-room/ToyRoomPhase.js';
import {ToyRoomEntities} from '../../../../src/js/toy-room/ToyRoomEntities.js';
import {BabyRenderer} from '../../../../src/js/entities/BabyRenderer.js';
import {GIRL_V2_SETS,GIRL_V2_FRAMES,GIRL_V2_REFERENCE_HEIGHT} from '../../../../src/js/assets/illustratedGirl.js';
import {ArenaPlayerRenderer} from '../../../../src/js/toy-room/ArenaPlayerRenderer.js';
import {createPlayerAnimation} from '../../../../src/js/toy-room/ArenaPlayerAnimation.js';
const ensure=(value,label)=>{if(!value)throw Error(label);};
const assets=review.game.assets,entities=new ToyRoomEntities(),baby=new BabyRenderer();
const canvas=document.querySelector('canvas');
const makeRoom=()=>new ToyRoomPhase(canvas,null,document.querySelector('#feedback'),null,{assets,bindInputs:false});
export async function audit(){
 let frames=0,transparent=0;
 for(const set of Object.values(GIRL_V2_SETS)){
  const image=assets.get(set.key);ensure(image,'Prancha carregada: '+set.key);
  const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);
  const rgba=ctx.getImageData(0,0,c.width,c.height).data;
  for(let p=3;p<rgba.length;p+=4)if(rgba[p]===0)transparent++;
  for(const frame of set.frames){let bottom=0,count=0;for(let y=0;y<frame.h;y++)for(let x=0;x<frame.w;x++)if(rgba[((frame.y+y)*c.width+frame.x+x)*4+3]){bottom=y+1;count++;}
   ensure(count>1000,'Arte detalhada presente');ensure(bottom===frame.anchorY,'Pé ancorado na última linha opaca');frames++;
  }
 }
 const occlusion=[];const sampleRoom=makeRoom();const options={assets,environmentTeddy:sampleRoom.environmentTeddy,environmentTrain:sampleRoom.environmentTrain};
 for(const toy of sampleRoom.toys)for(const facing of ['left','right'])for(const moving of [false,true]){
  const p={...sampleRoom.player,x:128,y:172,facing,isMoving:moving,animTime:7,carriedItem:{...toy,isCarried:true}};
  const before=JSON.stringify(p),pictures=[];
  for(const drawToy of [false,true])for(const front of [false,true]){
   const c=document.createElement('canvas');c.width=c.height=256;const actual=c.getContext('2d');let bodyDraws=0;
   const proxy=new Proxy(actual,{get(target,key){if(key==='drawImage')return(image,...args)=>{if(!drawToy&&image instanceof HTMLCanvasElement)return;if(image===assets.get('girl-v2-carry')){bodyDraws++;if(bodyDraws===2&&!front)return;}target.drawImage(image,...args);};const value=target[key];return typeof value==='function'?value.bind(target):value;},set(target,key,value){target[key]=value;return true;}});
   entities.renderPlayer(proxy,p,options);pictures.push(actual.getImageData(0,0,256,256).data);
  }
  let changed=0;for(let i=0;i<pictures[0].length;i+=4){let difference=0;for(let channel=0;channel<3;channel++)difference+=Math.abs((pictures[3][i+channel]-pictures[2][i+channel])-(pictures[1][i+channel]-pictures[0][i+channel]));if(difference>5)changed++;}
  ensure(changed>=2,'Dedos devem cobrir a frente do item: '+toy.type+'/'+facing+'/'+moving);ensure(JSON.stringify(p)===before,'Desenho não modifica jogador/item');occlusion.push({tipo:toy.type,facing,moving,pixelsDedos:changed});
 }
 sampleRoom.destroy();
 const interactions=[];
 for(const type of ['teddy','train','robot','bunny','duck','blocks','drum','jack']){
  const r=makeRoom(),toy=r.toys.find(t=>t.type===type);r.tutorial.finish();r.story.state.investigationStage='COLLECTING';
  r.player.x=toy.x;r.player.y=toy.y;r.lastActionTime=-10000;r.triggerAction();ensure(r.player.carriedItem===toy,'Coleta real de '+type);
  r.keysDown.ArrowRight=true;for(let i=0;i<24;i++)r.update(1);r.keysDown.ArrowRight=false;ensure(r.player.carriedItem===toy,'Caminhada conserva carga');
  const saved=r.snapshot(),restored=makeRoom();restored.restore(saved);ensure(restored.player.carriedItem===restored.toys.find(t=>t.id===toy.id),'Restore religa item por ID');restored.destroy();
  const chest=r.furniture.find(f=>f.id==='toy-chest');r.player.x=chest.x+chest.w/2;r.player.y=chest.y+chest.h/2;r.lastActionTime=-10000;r.triggerAction();ensure(r.player.carriedItem===null&&toy.isOrganized&&r.organizedCount===1,'Guardar no baú funciona');interactions.push(type);r.destroy();
 }
 const renderer=new ArenaPlayerRenderer();await renderer.load();let arenaSamples=0;
 for(const [pose,fields]of Object.entries({idle:{},run:{},attack:{attackTime:12},guard:{guarding:true},crouch:{crouching:true},jump:{jump:50,jumpVelocity:2},fall:{jump:50,jumpVelocity:-2},damage:{playerHitTime:18}}))for(const facing of ['left','right']){
  const c=document.createElement('canvas');c.width=600;c.height=420;
  const player={x:300,facing,isMoving:pose==='run'},state={mode:'BATTLE',jump:0,attackTime:0,playerHitTime:0,...fields};state.playerAnimation=createPlayerAnimation(state,player);state.playerAnimation.pose=pose;state.playerAnimation.poseTime=8;state.playerAnimation.guardAmount=pose==='guard'?1:0;
  const before=JSON.stringify(state);renderer.render(c.getContext('2d'),{player},state,360);ensure(JSON.stringify(state)===before,'Renderer da arena é puro');arenaSamples++;
 }
 return {frames,transparent,occlusion,interactions,arenaSamples};
}
export function carryingGallery(){
 const room=makeRoom(),output=document.createElement('canvas');output.width=1600;output.height=880;const ctx=output.getContext('2d');ctx.fillStyle='#e4cfb5';ctx.fillRect(0,0,1600,880);
 const modes=[['Direita • parada','right',false],['Direita • andando','right',true],['Esquerda • parada','left',false],['Esquerda • andando','left',true]];
 modes.forEach(([label,facing,isMoving],row)=>room.toys.forEach((toy,col)=>{
  const x=col*200+90,y=row*220+177;ctx.fillStyle='#563b31';ctx.font='14px sans-serif';ctx.fillText(toy.type, col*200+64,row*220+22);
  ctx.save();ctx.translate(x,y);ctx.scale(1.9,1.9);entities.renderPlayer(ctx,{...room.player,x:0,y:-28,carriedItem:{...toy,isCarried:true},facing,isMoving,animTime:7},{assets,environmentTeddy:room.environmentTeddy,environmentTrain:room.environmentTrain});ctx.restore();
 }));room.destroy();return output.toDataURL().split(',')[1];
}
export function poseGallery(){
 const poses=Object.keys(GIRL_V2_FRAMES).filter(p=>!['push','interact'].includes(p));const c=document.createElement('canvas');c.width=1280;c.height=Math.ceil(poses.length/8)*210;const ctx=c.getContext('2d');ctx.fillStyle='#d9d5c8';ctx.fillRect(0,0,c.width,c.height);
 poses.forEach((pose,index)=>{const x=index%8*160+75,y=Math.floor(index/8)*210+184;ctx.fillStyle='#423328';ctx.font='13px sans-serif';ctx.fillText(pose,index%8*160+10,Math.floor(index/8)*210+20);baby.renderPose(ctx,assets,pose,pose==='sword_attack'?3:0,x,y,135);});return c.toDataURL().split(',')[1];
}
export function roomShot(type='teddy',moving=false){
 const r=makeRoom();r.tutorial.finish();r.introAlpha=0;r.introBannerTimer=0;
 const toy=r.toys.find(t=>t.type===type);Object.assign(r.player,{x:750,y:700,carriedItem:toy,isMoving:moving,animTime:7});toy.isCarried=true;r.cameraX=750-canvas.width/2;r.cameraY=700-canvas.height/2;r.render();const result=canvas.toDataURL().split(',')[1];r.destroy();return result;
}

/** Amostra os quatro atores usando manifestos, trajetórias e compositor reais da arena. */
export async function chestGallery(){
 const r=makeRoom();r.arena.configurePresentation();r.battle.activate();await Promise.all([r.battle.readyPromise,r.arena.readyPromise]);
 ensure(r.battle.ready&&!r.battle.error,'Inimigos carregados');
 const stages=[0,.18,.35,.6,1],actors=['train','robot','dinosaur','bear'];
 const gallery=document.createElement('canvas');gallery.width=1800;gallery.height=1200;const ctx=gallery.getContext('2d');
 const savedPresentation=r.battle.presentation;r.battle.presentation={...savedPresentation,cameraFrame:()=>({scale:.8,ox:-840,oy:-210}),renderHUD:()=>{},renderPlayer:()=>{},renderFX:()=>{}};
 const placements=[];
 for(let row=0;row<actors.length;row++)for(let col=0;col<stages.length;col++){
  const actor=actors[row],progress=stages[col];r.battle.state.enemy={...r.battle.state.enemy,actor,x:1120};
  r.battle.state.transition={elapsed:progress*BATTLE_TRANSITION_DURATION,incoming:{...r.battle.state.enemy},outgoing:null};
  const before=JSON.stringify(r.battle.state);const p=r.battle.transitionPlacement(true);r.battle.render();ensure(before===JSON.stringify(r.battle.state),'Transporte e desenho não alteram simulação');
  ctx.drawImage(canvas,0,0,Math.min(canvas.width,360),Math.min(canvas.height,300),col*360,row*300,360,300);ctx.fillStyle='#fff';ctx.font='16px sans-serif';ctx.fillText(actor+' '+progress,col*360+12,row*300+22);
  placements.push({actor,progress,x:p.x,y:p.y,scale:p.transportScale});
  if(col===0)ensure(p.transportScale===.16,'Começa pequeno dentro da caixa');
  if(col===4)ensure(p.x===1120&&p.y===690&&p.transportScale===1,'Pousa no ponto original');
 }
 r.battle.presentation=savedPresentation;r.battle.state.transition=null;r.player.x=700;r.battle.render();const scene=canvas.toDataURL().split(',')[1];
 const c=document.createElement('canvas');c.width=1800;c.height=800;const mask=c.getContext('2d');mask.fillStyle='#ff00ff';mask.fillRect(0,0,c.width,c.height);renderArenaTemple(mask,r,r.arena.layout,true);
 // A frente deve cobrir a parede do baú, mas deixar o miolo da abertura livre.
 const chest=r.arena.layout.structures.find(s=>s.sourceId==='toy-chest'),w=chest.w+8*chest.scale,h=w;const x=chest.x-4*chest.scale,y=chest.footY-h;
 const pixel=(u,v)=>[...mask.getImageData(Math.floor(x+w*u),Math.floor(y+h*v),1,1).data];
 ensure(pixel(.4,.8).join(',')!=='255,0,255,255','Parede frontal encobre o brinquedo');ensure(pixel(.4,.5).join(',')==='255,0,255,255','Abertura não é coberta pela camada frontal');
 r.destroy();return {gallery:gallery.toDataURL().split(',')[1],scene,placements};
}
